package com.taller.portal.model;
import jakarta.persistence.*; import java.time.*;
/** Cliente registrado; conserva expedientes suspendidos mediante soft delete. */
@Entity @Table(name="clientes",uniqueConstraints={@UniqueConstraint(name="uk_cliente_nombre_nacimiento",columnNames={"nombre_completo","fecha_nacimiento"})}) public class Cliente { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) @JoinColumn(name="taller_id",nullable=false) public Taller taller; @ManyToOne(optional=false) @JoinColumn(name="status_id",nullable=false) public StatusCatalog status; @Column(name="is_deleted",nullable=false) public boolean isDeleted; @Column(name="deleted_at") public LocalDateTime deletedAt; @ManyToOne @JoinColumn(name="deleted_by") public User deletedBy; @Column(name="nombre_completo",nullable=false,length=120) public String nombreCompleto; @Column(nullable=false,length=120) public String contactoAlternativo; @Column(nullable=false) public Integer edad; @Column(nullable=false) public LocalDate fechaNacimiento; @Column(nullable=false,unique=true,length=25) public String telefonoPersonal; @Column(nullable=false,unique=true,length=25) public String telefonoTrabajo; @Column(nullable=false,unique=true,length=140) public String email; @Column(unique=true,length=140) public String emailTrabajo; @Column(nullable=false,length=255) public String fotografiaRuta; @Column(nullable=false,length=120) public String calle; @Column(nullable=false,length=100) public String colonia; @Column(nullable=false,length=100) public String municipio; @Column(nullable=false,length=100) public String estado; @Column(nullable=false,length=10) public String codigoPostal; @Column(nullable=false,unique=true,length=80) public String idempotencyKey; }
